BEGIN;
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid REFERENCES entities(id),name varchar(500) NOT NULL,mime_type varchar(150),storage_key text NOT NULL UNIQUE,sha256 char(64),size_bytes bigint CHECK(size_bytes>=0),uploaded_by uuid REFERENCES users(id),classification varchar(100),status varchar(20) NOT NULL DEFAULT 'UPLOADED' CHECK(status IN ('UPLOADED','QUARANTINED','SCANNED','APPROVED','REJECTED','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS document_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,version_number integer NOT NULL CHECK(version_number>0),storage_key text NOT NULL,sha256 char(64),uploaded_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,version_number));
CREATE TABLE IF NOT EXISTS file_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,scanner_name varchar(100) NOT NULL,scan_status varchar(30) NOT NULL CHECK(scan_status IN ('PENDING','CLEAN','SUSPICIOUS','MALICIOUS','ERROR')),risk_score numeric(5,2),contains_pii boolean,contains_tax_id boolean,contains_bank_info boolean,details jsonb NOT NULL DEFAULT '{}'::jsonb,scanned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),comment text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_documents_entity_created ON documents(entity_id,created_at DESC);
COMMIT;
